def maximum_subsequence_xor(nums):
    basis=[0]*31
    for value in nums:
        while value:
            bit=value.bit_length()-1
            if basis[bit]:value^=basis[bit]
            else:basis[bit]=value;break
    answer=0
    for bit in range(30,-1,-1):answer=max(answer,answer^basis[bit])
    return answer

